import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import {
  SVS_GLB_ROTATION_Y,
  destinationPoint,
  directionToAzEl,
  greatCircleDistanceM,
  latLonToLocalM,
  latLonToUv,
  latLonToVector3,
  localMToLatLon,
  normalizeLon,
  rotateY,
  svsGlbDirectionFromUv,
  uvToLatLon,
  vector3ToLatLon,
} from "../src";

// 720x360 grayscale LROC albedo, 0.5°/px, row 0 = 90°N, col 0 = 180°W.
// Generated by scripts/make_test_fixtures.py from the CGI Moon Kit preview.
const albedo = readFileSync(fileURLToPath(new URL("./fixtures/lroc-albedo-720x360.u8", import.meta.url)));
const W = 720;
const H = 360;

/** Mean albedo in a (2r+1)^2 pixel window around the texel that latLonToUv() picks. */
function albedoAt(lat: number, lon: number, r = 1): number {
  const { u, v } = latLonToUv(lat, lon);
  const c0 = Math.floor(u * W);
  const r0 = Math.floor(v * H);
  let sum = 0;
  let n = 0;
  for (let dr = -r; dr <= r; dr++) {
    for (let dc = -r; dc <= r; dc++) {
      const row = Math.min(H - 1, Math.max(0, r0 + dr));
      const col = (c0 + dc + W) % W;
      sum += albedo[row * W + col];
      n++;
    }
  }
  return sum / n;
}

const globalMean = albedo.reduce((a, b) => a + b, 0) / albedo.length;

const APOLLO_11 = { lat: 0.67416, lon: 23.47314 };

function expectVecClose(a: { x: number; y: number; z: number }, b: { x: number; y: number; z: number }, eps = 1e-9) {
  expect(Math.abs(a.x - b.x)).toBeLessThan(eps);
  expect(Math.abs(a.y - b.y)).toBeLessThan(eps);
  expect(Math.abs(a.z - b.z)).toBeLessThan(eps);
}

describe("latLonToVector3", () => {
  it("puts lon 0 on +Z, 90°E on +X and the north pole on +Y", () => {
    expectVecClose(latLonToVector3(0, 0), { x: 0, y: 0, z: 1 });
    expectVecClose(latLonToVector3(0, 90), { x: 1, y: 0, z: 0 });
    expectVecClose(latLonToVector3(90, 0), { x: 0, y: 1, z: 0 });
    expectVecClose(latLonToVector3(-90, 0), { x: 0, y: -1, z: 0 });
  });

  it("round-trips through vector3ToLatLon", () => {
    for (const [lat, lon] of [[0.674, 23.473], [-89.5, -137.3], [45, 179.9], [-12.3, -45.6]]) {
      const back = vector3ToLatLon(latLonToVector3(lat, lon, 1737.4));
      expect(back.lat).toBeCloseTo(lat, 9);
      expect(back.lon).toBeCloseTo(lon, 9);
    }
  });

  it("matches the NASA SVS GLB after its Y rotation", () => {
    for (const [lat, lon] of [[0, 0], [0, 90], [0.674, 23.473], [-80.13, 1.44], [30, -120]]) {
      const { u, v } = latLonToUv(lat, lon);
      const glbDir = svsGlbDirectionFromUv(u, v);
      expectVecClose(rotateY(glbDir, SVS_GLB_ROTATION_Y), latLonToVector3(lat, lon), 1e-9);
    }
  });
});

describe("texture mapping (LROC map centred on lon 0)", () => {
  it("puts Apollo 11 on dark mare basalt (Mare Tranquillitatis)", () => {
    const a11 = albedoAt(APOLLO_11.lat, APOLLO_11.lon);
    expect(a11).toBeLessThan(globalMean * 0.8);
    // Mare Tranquillitatis interior (around 8.5°N 31.4°E) is dark as well…
    expect(albedoAt(8.5, 31.4)).toBeLessThan(globalMean * 0.8);
    // …while the Descartes highlands (Apollo 16) and Tycho's region are bright.
    expect(albedoAt(-8.97, 15.5)).toBeGreaterThan(globalMean);
    expect(albedoAt(-40, -10)).toBeGreaterThan(globalMean);
  });

  it("would fail with a 180° longitude offset (guards against a flipped map)", () => {
    expect(albedoAt(APOLLO_11.lat, APOLLO_11.lon + 180)).toBeGreaterThan(globalMean);
  });

  it("uv round-trip", () => {
    const { u, v } = latLonToUv(APOLLO_11.lat, APOLLO_11.lon);
    const back = uvToLatLon(u, v);
    expect(back.lat).toBeCloseTo(APOLLO_11.lat, 9);
    expect(back.lon).toBeCloseTo(APOLLO_11.lon, 9);
  });
});

describe("local geometry", () => {
  it("normalizes longitudes", () => {
    expect(normalizeLon(190)).toBe(-170);
    expect(normalizeLon(-180)).toBe(180);
    expect(normalizeLon(360)).toBe(0);
  });

  it("computes azimuth/elevation of a direction", () => {
    // At the equator / lon 0, +Y is north on the horizon and +Z is the zenith.
    const n = directionToAzEl(0, 0, { x: 0, y: 1, z: 0 });
    expect(n.azimuthDeg).toBeCloseTo(0, 9);
    expect(n.elevationDeg).toBeCloseTo(0, 9);
    const e = directionToAzEl(0, 0, { x: 1, y: 0, z: 0 });
    expect(e.azimuthDeg).toBeCloseTo(90, 9);
    const z = directionToAzEl(0, 0, { x: 0, y: 0, z: 1 });
    expect(z.elevationDeg).toBeCloseTo(90, 9);
  });

  it("destinationPoint and greatCircleDistanceM agree", () => {
    const start = { lat: -89.5, lon: 45 };
    for (const az of [0, 73, 180, 271]) {
      const p = destinationPoint(start, az, 25_000);
      expect(greatCircleDistanceM(start, p)).toBeCloseTo(25_000, 3);
    }
  });

  it("azimuthal-equidistant projection round-trips near the south pole", () => {
    const c = { lat: -89.45, lon: -137.31 };
    for (const [x, y] of [[0, 0], [1200, -300], [-5000, 7000], [15000, 15000]]) {
      const ll = localMToLatLon(c, x, y);
      const back = latLonToLocalM(c, ll);
      expect(back.x).toBeCloseTo(x, 4);
      expect(back.y).toBeCloseTo(y, 4);
    }
  });
});
